// examples/two_moons.cpp
#include "pyra/pyra.h"
using namespace pyra;

int main() {
  init(/*device=*/0);
  std::mt19937 rng(0);

  // --- data: sklearn's two moons, generated by hand because sklearn is a
  //     dependency and dependencies are the enemy.
  auto [X, y] = make_two_moons(/*n=*/1500, /*noise=*/0.16f, rng);  // [1500,2] f32, [1500] i32
  Tensor x = X, target = y;

  // --- model: the smallest network that makes this article honest
  struct Net : nn::Module {
    nn::Linear l1, l2, l3;
    Net(std::mt19937& r) : l1(2, 64, r), l2(64, 64, r), l3(64, 2, r) {
      register_child(&l1); register_child(&l2); register_child(&l3);
    }
    Tensor forward(const Tensor& x) override {
      return l3(gelu(l2(gelu(l1(x)))));      // 4,482 parameters of pure spite
    }
  } net(rng);

  Adam optim(net.parameters(), /*lr=*/3e-3f);

  for (int step = 0; step < 1200; ++step) {
    auto [xb, yb] = sample_batch(x, target, /*bs=*/256, rng);   // host-side indices
    Tensor logits = net(xb);                 // forward: 8 kernels, tape grows by 8
    Tensor loss   = cross_entropy(logits, yb);   // fused softmax+nll, stable
    backward(loss);                        // reverse walk: ~14 kernels
    optim.step();                          // 6 fused adam kernels, grads zeroed inside
    if (step % 100 == 0 || step == 1199)
      std::printf("step %4d  loss %.4f\n", step, item(loss));
  }

  NoGradGuard ng;                            // <- or: hockey-stick VRAM graph
  std::printf("accuracy: %.1f%%\n", 100.0 * accuracy(net, x, target));
}
